<?php $isEdit=!empty($product); ?>
<div class="admin-card"><div class="admin-card-body"><form method="post" enctype="multipart/form-data"><?= csrf_field() ?><div class="row g-4"><div class="col-lg-8"><div class="row g-3"><div class="col-md-8"><label class="form-label">Nama produk</label><input class="form-control" name="name" value="<?= e($_POST['name']??$product['name']??'') ?>" required></div><div class="col-md-4"><label class="form-label">SKU</label><input class="form-control" name="sku" value="<?= e($_POST['sku']??$product['sku']??'') ?>" required></div><div class="col-md-6"><label class="form-label">Kategori</label><select class="form-select" name="category_id" required><option value="">Pilih kategori</option><?php foreach($categories as $category):?><option value="<?= $category['id'] ?>" <?= (int)($_POST['category_id']??$product['category_id']??0)===(int)$category['id']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Harga</label><input class="form-control" type="number" name="price" min="0" step="100" value="<?= e($_POST['price']??$product['price']??0) ?>" required></div><div class="col-md-3"><label class="form-label">Batas stok</label><input class="form-control" type="number" name="minimum_stock" min="0" value="<?= e($_POST['minimum_stock']??$product['minimum_stock']??5) ?>" required></div><?php if(!$isEdit):?><div class="col-md-4"><label class="form-label">Stok awal</label><input class="form-control" type="number" name="stock" min="0" value="<?= e($_POST['stock']??0) ?>" required></div><?php endif;?><div class="col-12"><label class="form-label">Deskripsi</label><textarea class="form-control" name="description" rows="6"><?= e($_POST['description']??$product['description']??'') ?></textarea></div></div></div><div class="col-lg-4"><label class="form-label">Foto produk</label><?php if($isEdit):?><img class="w-100 rounded-3 mb-2" style="aspect-ratio:4/3;object-fit:cover" src="<?= e(product_image($product['image'])) ?>"><?php endif;?><input class="form-control mb-3" type="file" name="image" accept="image/jpeg,image/png,image/webp" <?= $isEdit?'':'required' ?>><div class="form-check form-switch mb-2"><input class="form-check-input" type="checkbox" name="is_featured" value="1" <?= !empty($_POST)?isset($_POST['is_featured']):(!empty($product['is_featured'])?'checked':'') ?>><label class="form-check-label">Produk unggulan</label></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="is_active" value="1" <?= !empty($_POST)?isset($_POST['is_active']):(!isset($product)||!empty($product['is_active'])?'checked':'') ?>><label class="form-check-label">Produk aktif</label></div></div><div class="col-12 d-flex gap-2"><button class="btn btn-primary">Simpan Produk</button><a class="btn btn-light" href="<?= url('admin/products.php') ?>">Batal</a></div></div></form></div></div>
